import{_ as a,b as e,c as t,I as n}from"./chunks/framework.C6cPs9Ia.js";const u=JSON.parse('{"title":"博客改造日志：从 Mizuki 到蔚蓝档案","description":"博客第三次大改造，迁移到 vitepress-theme-bluearchive 主题的完整记录","frontmatter":{"title":"博客改造日志：从 Mizuki 到蔚蓝档案","date":"2026-09-14T00:00:00.000Z","tags":["建站","技术笔记"],"pinned":true,"cover":"/LQY/images/cover-b.jpg","head":[["meta",{"name":"description","content":"博客第三次大改造，迁移到 vitepress-theme-bluearchive 主题的完整记录"}],["meta",{"name":"keywords","content":"VitePress, 蔚蓝档案主题, 博客改造, giscus"}]]},"headers":[],"relativePath":"posts/theme-migration.md","filePath":"posts/theme-migration.md"}'),l={name:"posts/theme-migration.md"};function o(r,s,p,i,c,d){return e(),t("div",null,[...s[0]||(s[0]=[n(`<p>博客的第三次大装修：从 Astro 的 Mizuki 主题搬家到 VitePress 的蔚蓝档案主题，附踩坑全记录。</p><hr><h2 id="为什么又搬家了" tabindex="-1">为什么又搬家了 <a class="header-anchor" href="#为什么又搬家了" aria-label="Permalink to &quot;为什么又搬家了&quot;">​</a></h2><p>严格来说这是本博客的<strong>第三次装修</strong>：</p><ol><li><strong>一代目</strong>：手写静态页，HTML + CSS 从零搓，属于&quot;能用但丑&quot;阶段</li><li><strong>二代目</strong>：Astro + Mizuki 主题，粉粉的，很可爱，但总觉得少了点什么</li><li><strong>三代目</strong>：就是现在！<a href="https://github.com/Alittfre/vitepress-theme-bluearchive" target="_blank" rel="noreferrer">vitepress-theme-bluearchive</a></li></ol><p>少的那点东西，就是<strong>蔚蓝档案</strong>的味儿。第一次打开作者大大的 <a href="https://vitepress-theme-bluearchive.vercel.app/" target="_blank" rel="noreferrer">demo</a>，看到阿罗娜在右下角歪头的那一刻，我就知道：就是这个了。</p><h2 id="迁移清单" tabindex="-1">迁移清单 <a class="header-anchor" href="#迁移清单" aria-label="Permalink to &quot;迁移清单&quot;">​</a></h2><p>实际动手的部分比想象中多，列个清单备查：</p><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文章迁移</td><td>旧文章全部重写为 VitePress frontmatter 格式</td></tr><tr><td>子路径适配</td><td><code>base: &#39;/LQY/&#39;</code>，逐处修正绝对路径引用</td></tr><tr><td>评论系统</td><td>Gitalk → <strong>giscus</strong>（复用旧仓库的 Discussions 配置）</td></tr><tr><td>搜索</td><td>minisearch，主题自带，开箱即用</td></tr><tr><td>RSS</td><td>主题没做，自己写了个构建前生成脚本</td></tr><tr><td>看板娘</td><td>阿罗娜 + 普拉娜，Spine 模型路径加 base 前缀</td></tr><tr><td>字体</td><td>Blueaka 游戏字体，按 unicode 分包按需加载</td></tr></tbody></table><h2 id="最花时间的一步-base-路径" tabindex="-1">最花时间的一步：base 路径 <a class="header-anchor" href="#最花时间的一步-base-路径" aria-label="Permalink to &quot;最花时间的一步：base 路径&quot;">​</a></h2><p>GitHub Pages 的项目页部署在 <code>/LQY/</code> 子路径下，而主题里有些硬编码的 <code>/</code> 开头路径，部署上去全是 404。需要改的有三类：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#586E75;font-style:italic;">// 1. config.mts 里的 head 链接</span></span>
<span class="line"><span style="color:#839496;">[</span><span style="color:#2AA198;">&#39;link&#39;</span><span style="color:#839496;">, { rel: </span><span style="color:#2AA198;">&#39;stylesheet&#39;</span><span style="color:#839496;">, href: </span><span style="color:#2AA198;">&#39;/LQY/font/Blueaka/Blueaka.css&#39;</span><span style="color:#839496;"> }]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">// 2. Spine 模型资源路径（运行时拼 base 前缀）</span></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">const</span><span style="color:#268BD2;"> fixUrl</span><span style="color:#859900;"> =</span><span style="color:#839496;"> (p) </span><span style="color:#93A1A1;font-weight:bold;">=&gt;</span><span style="color:#839496;"> (</span><span style="color:#268BD2;">p</span><span style="color:#839496;">.</span><span style="color:#268BD2;">startsWith</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&#39;/&#39;</span><span style="color:#839496;">) </span><span style="color:#859900;">?</span><span style="color:#268BD2;"> siteBase</span><span style="color:#839496;">.</span><span style="color:#268BD2;">replace</span><span style="color:#839496;">(</span><span style="color:#DC322F;">/</span><span style="color:#CB4B16;">\\/</span><span style="color:#859900;">$</span><span style="color:#DC322F;">/</span><span style="color:#839496;">, </span><span style="color:#2AA198;">&#39;&#39;</span><span style="color:#839496;">) </span><span style="color:#859900;">+</span><span style="color:#268BD2;"> p</span><span style="color:#859900;"> :</span><span style="color:#268BD2;"> p</span><span style="color:#839496;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#586E75;font-style:italic;">// 3. 文章 frontmatter 里的封面（不会自动加前缀）</span></span>
<span class="line"><span style="color:#839496;">cover: </span><span style="color:#859900;">/</span><span style="color:#268BD2;">LQY</span><span style="color:#859900;">/</span><span style="color:#268BD2;">images</span><span style="color:#859900;">/</span><span style="color:#268BD2;">cover</span><span style="color:#859900;">-</span><span style="color:#268BD2;">b</span><span style="color:#839496;">.</span><span style="color:#268BD2;">jpg</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">踩坑提示</p><p>VitePress 的 markdown 里的图片<strong>会</strong>自动加 base，但 frontmatter 自定义字段和组件里绑定的路径<strong>不会</strong>。这两者的区别让我排查了整整一节晚自习。</p></div><h2 id="为什么把-gitalk-换成-giscus" tabindex="-1">为什么把 Gitalk 换成 giscus <a class="header-anchor" href="#为什么把-gitalk-换成-giscus" aria-label="Permalink to &quot;为什么把 Gitalk 换成 giscus&quot;">​</a></h2><p>主题默认用 Gitalk，但它需要手动去 GitHub 申请一个 OAuth 应用，而且 issue 会越积越多。giscus 用的是 Discussions：</p><ul><li>不用申请任何东西，装个 App 就完事</li><li>评论区就是 Discussions 的帖子，手机上也能看</li><li>可以跟主题的夜间模式联动（改一行 <code>data-theme</code> 的事）</li></ul><p>顺手还做了个小优化：评论只在<strong>文章页</strong>挂载，首页、标签页、友链页都不加载，省一点首屏请求。</p><h2 id="最后" tabindex="-1">最后 <a class="header-anchor" href="#最后" aria-label="Permalink to &quot;最后&quot;">​</a></h2><p>现在的成果就是你在看的这个站。横幅、字体、点击特效、看板娘，全部 BA 味儿拉满。</p><p>下一步的计划：把旧文章里那些粉色调的配图重新截一轮，让全站风格统一。以及，先把下周的月考应付过去（悲）。</p>`,20)])])}const b=a(l,[["render",o]]);export{u as __pageData,b as default};
